import {chromium,webkit} from 'playwright';import fs from 'node:fs';import assert from 'node:assert/strict';const engine=process.env.BROWSER??'chromium',out=`qa-output/${engine}`;fs.mkdirSync(out,{recursive:true});const browser=await({chromium,webkit}[engine]).launch({headless:true,args:engine==='chromium'?['--use-angle=swiftshader']:[]});const results=[];
try{for(const id of ['03','05']){const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});page.setDefaultTimeout(120000);const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});try{await page.goto(`http://127.0.0.1:8765/trees.html?case=${id}`,{waitUntil:'networkidle'});await page.waitForFunction(()=>window.__plantStudy?.treeReady);await page.waitForTimeout(600);const e=await page.evaluate(()=>window.__plantStudy.study.evidence());assert.ok(e.connected);assert.ok(e.growthVContinuous);assert.equal(e.barkApplied,false);assert.equal(e.holes,2);assert.ok(e.volumeCore?.axisIdentityTransferred);assert.ok(e.volumeCore?.innerCapsules>0);assert.ok(e.volumeCore?.topology.closed);await page.screenshot({path:`${out}/tree-${id}-default.png`});if(id==='03'){await page.locator('#needles').uncheck();await page.waitForTimeout(300);await page.screenshot({path:`${out}/tree-${id}-skeleton.png`});}await page.locator('#side').click();await page.waitForTimeout(300);await page.screenshot({path:`${out}/tree-${id}-side.png`});await page.locator('#near').click();await page.waitForTimeout(300);await page.screenshot({path:`${out}/tree-${id}-macro.png`});await page.locator('#core-axis-map').check();await page.waitForTimeout(300);await page.screenshot({path:`${out}/tree-${id}-axis-map.png`});await page.locator('#core-axis-map').uncheck();const old=await page.evaluate(()=>window.__plantStudy.study.core.stats.triangles);await page.locator('#core-blend').evaluate(el=>el.value='.36');await page.locator('#rebuild-core').click();await page.waitForTimeout(500);const rebuilt=await page.evaluate(()=>window.__plantStudy.study.core.stats);assert.equal(rebuilt.blend,.36);assert.ok(rebuilt.topology.closed);assert.notEqual(rebuilt.triangles,old);await page.screenshot({path:`${out}/tree-${id}-rebuilt-core.png`});assert.deepEqual(errors,[]);results.push({case:id,...e,passed:true,errors,visualAcceptance:false});}catch(error){results.push({case:id,passed:false,error:error.stack,errors});await page.screenshot({path:`${out}/tree-${id}-failure.png`}).catch(()=>{});throw error;}finally{await page.close();}}}finally{fs.writeFileSync(`${out}/tree-result.json`,JSON.stringify({engine,results},null,2));await browser.close();}
